openMemoryDirectory.raw_text:
func openMemoryDirectory(directory string) (*os.Root, error) {
	if !filepath.IsAbs(directory) || filepath.Clean(directory) != directory {
		return nil, errors.New("Vault delivery requires a clean absolute directory")
	}
	info, err := os.Lstat(directory)
	if err != nil || !info.IsDir() || info.Mode().Perm() != 0o700 {
		return nil, errors.New("Vault delivery directory must exist with mode 0700")
	}
	root, err := os.OpenRoot(directory)
	if err != nil {
		return nil, err
	}
	fail := func() (*os.Root, error) {
		root.Close()
		return nil, errors.New("Vault delivery needs an owner-only tmpfs directory with swap disabled")
	}
	file, err := root.Open(".")
	if err != nil {
		return fail()
	}
	defer file.Close()
	info, err = file.Stat()
	if err != nil || info.Mode().Perm() != 0o700 || info.Sys().(*syscall.Stat_t).Uid != uint32(os.Geteuid()) {
		return fail()
	}
	var fs unix.Statfs_t
	if err := unix.Fstatfs(int(file.Fd()), &fs); err != nil || fs.Type != unix.TMPFS_MAGIC {
		return fail()
	}
	if !SwapOff() {
		return fail()
	}
	return root, nil
}

RequireMemoryFilesystem.raw_text:
func RequireMemoryFilesystem(directory string) error {
	file, err := os.Open(directory)
	if err != nil {
		return err
	}
	defer file.Close()
	var fs unix.Statfs_t
	if err := unix.Fstatfs(int(file.Fd()), &fs); err != nil || fs.Type != unix.TMPFS_MAGIC || !SwapOff() {
		return errors.New("Vault runtime files require tmpfs with swap disabled")
	}
	return nil
}

SwapOff.raw_text:
func SwapOff() bool {
	var info unix.Sysinfo_t
	return unix.Sysinfo(&info) == nil && info.Totalswap == 0
}

writeMemoryFile.raw_text:
func writeMemoryFile(root *os.Root, name string, data []byte) error {
	defer clear(data)
	if filepath.Base(name) != name || name == "." || name == ".." {
		return errors.New("Vault delivery requires a simple file name")
	}
	// The directory's ownership prevents another UID from changing this
	// temporary name; O_EXCL also refuses an existing file or symlink.
	temporary := "." + name + ".pending-" + rand.Text()
	file, err := root.OpenFile(temporary, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	defer root.Remove(temporary)
	_, err = file.Write(data)
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	if err != nil {
		return err
	}
	return root.Rename(temporary, name)
}

Name.raw_text:
func Name(scope, key string) string {
	return scope + "-" + strings.ToLower(strings.ReplaceAll(key, "_", "-"))
}

Ensure.raw_text:
func Ensure(ctx context.Context, client VaultClient, target Target, name, description string, value func(context.Context) (string, error)) (Stored, error) {
	stored := Stored{Secret: name}
	if err := safeEnv(); err != nil {
		return stored, err
	}
	id, provisioning, err := lookup(ctx, client, target, name)
	if err != nil || id != "" {
		stored.ID = id
		stored.Provisioning = provisioning
		return stored, err
	}
	secret, err := value(ctx)
	if err != nil {
		return stored, err
	}
	content := base64.StdEncoding.EncodeToString([]byte(secret))
	response, err := client.CreateSecret(ctx, ocivault.CreateSecretRequest{
		CreateSecretDetails: ocivault.CreateSecretDetails{
			CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), KeyId: new(target.KeyID),
			SecretName: new(name), Description: new(description),
			SecretContent: ocivault.Base64SecretContentDetails{Content: new(content), Stage: ocivault.SecretContentDetailsStageCurrent},
		},
		// The SDK retries a lost response with the same token, which OCI
		// answers with the first result instead of a second secret.
		OpcRetryToken: new(uuid.New().String()),
	})
	if err != nil {
		if id, provisioning, lookupErr := lookup(ctx, client, target, name); lookupErr == nil && id != "" {
			stored.ID, stored.Provisioning = id, provisioning
			return stored, nil
		}
		return stored, fmt.Errorf("create Vault secret %s failed", name)
	}
	if response.Id == nil || !secretOCIDRE.MatchString(*response.Id) {
		return stored, fmt.Errorf("create Vault secret %s: OCI returned no secret OCID", name)
	}
	stored.ID, stored.Created = *response.Id, true
	return stored, nil
}

lookup.raw_text:
func lookup(ctx context.Context, client VaultClient, target Target, name string) (string, bool, error) {
	found := ""
	provisioning := false
	request := ocivault.ListSecretsRequest{CompartmentId: new(target.CompartmentID), VaultId: new(target.VaultID), Name: new(name)}
	for range 32 {
		response, err := client.ListSecrets(ctx, request)
		if err != nil {
			return "", false, fmt.Errorf("list Vault secret %s failed", name)
		}
		for _, item := range response.Items {
			if item.SecretName == nil || *item.SecretName != name {
				continue
			}
			if item.Id == nil || !secretOCIDRE.MatchString(*item.Id) || found != "" ||
				item.LifecycleState != ocivault.SecretSummaryLifecycleStateActive &&
					item.LifecycleState != ocivault.SecretSummaryLifecycleStateCreating {
				return "", false, fmt.Errorf("Vault secret %s exists in state %s; inspect it before rerunning", name, item.LifecycleState)
			}
			found = *item.Id
			provisioning = item.LifecycleState == ocivault.SecretSummaryLifecycleStateCreating
		}
		if response.OpcNextPage == nil {
			return found, provisioning, nil
		}
		request.Page = response.OpcNextPage
	}
	return "", false, fmt.Errorf("list Vault secret %s: too many pages", name)
}

Read.raw_text:
func Read(ctx context.Context, client BundleClient, vaultID, name string) (string, error) {
	response, err := readBundle(ctx, client, vaultID, name)
	if err != nil {
		return "", err
	}
	return decodeBundle(response.SecretBundle, name)
}

ReadVersioned.raw_text:
func ReadVersioned(ctx context.Context, client BundleClient, vaultID, name string) (VersionedValue, error) {
	response, err := readBundle(ctx, client, vaultID, name)
	if err != nil {
		return VersionedValue{}, err
	}
	bundle := response.SecretBundle
	if bundle.SecretId == nil || *bundle.SecretId == "" || bundle.VersionNumber == nil || *bundle.VersionNumber <= 0 {
		return VersionedValue{}, fmt.Errorf("Vault secret %s has no authoritative version", name)
	}
	value, err := decodeBundle(bundle, name)
	if err != nil {
		return VersionedValue{}, err
	}
	if strings.ContainsRune(value, 0) {
		return VersionedValue{}, fmt.Errorf("Vault secret %s does not fit an environment variable", name)
	}
	return VersionedValue{Value: value, SecretID: *bundle.SecretId, Number: *bundle.VersionNumber}, nil
}

readBundle.raw_text:
func readBundle(ctx context.Context, client BundleClient, vaultID, name string) (ocisecrets.GetSecretBundleByNameResponse, error) {
	if err := safeEnv(); err != nil {
		return ocisecrets.GetSecretBundleByNameResponse{}, err
	}
	response, err := client.GetSecretBundleByName(ctx, ocisecrets.GetSecretBundleByNameRequest{
		SecretName: new(name), VaultId: new(vaultID), Stage: ocisecrets.GetSecretBundleByNameStageCurrent,
	})
	if err != nil {
		return response, &readError{name: name, cause: err}
	}
	return response, nil
}

decodeBundle.raw_text:
func decodeBundle(bundle ocisecrets.SecretBundle, name string) (string, error) {
	var content *string
	switch bundle := bundle.SecretBundleContent.(type) {
	case ocisecrets.Base64SecretBundleContentDetails:
		content = bundle.Content
	case *ocisecrets.Base64SecretBundleContentDetails:
		if bundle != nil {
			content = bundle.Content
		}
	}
	if content == nil {
		return "", fmt.Errorf("Vault secret %s has no base64 content", name)
	}
	if len(*content) > base64.StdEncoding.EncodedLen(maxValue) {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	value, err := base64.StdEncoding.Strict().DecodeString(*content)
	if err != nil {
		return "", fmt.Errorf("Vault secret %s is not base64", name)
	}
	if len(value) > maxValue {
		return "", fmt.Errorf("Vault secret %s exceeds %d bytes", name, maxValue)
	}
	return string(value), nil
}

Ref.region.raw_text:
func (r Ref) region() string {
	match := vaultOCIDRE.FindStringSubmatch(r.Vault)
	if match == nil || len(r.Vault) > 255 || !catalog.IsOCIRegion(match[1]) {
		return ""
	}
	return match[1]
}

ValidateRefs.raw_text:
func ValidateRefs(cell, role string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs {
		return fmt.Errorf("%s has more than %d Vault secrets", role, MaxRefs)
	}
	if len(refs) != 0 && slices.ContainsFunc(infrastructure, func(family string) bool {
		return role == family || strings.HasPrefix(role, family+"-") || strings.HasPrefix(family, role+"-")
	}) {
		return fmt.Errorf("role %s shares a name with the cell's infrastructure secrets and names no Vault secrets", role)
	}
	return ValidateDeliveryRefs(cell, role, refs, env)
}

ValidateDeliveryRefs.raw_text:
func ValidateDeliveryRefs(cell, service string, refs map[string]Ref, env map[string]string) error {
	if len(refs) > MaxRefs || !nameRE.MatchString(service) {
		return errors.New("Vault delivery needs a service name and at most 64 references")
	}
	entry, known := catalog.LookupName(cell)
	files := map[string]bool{}
	for key, ref := range refs {
		if !known || ref.region() != entry.OCIRegion {
			return fmt.Errorf("Vault secret %s of %s must name a Vault in cell %s's region", key, service, cell)
		}
		if !envKeyRE.MatchString(key) {
			return fmt.Errorf("Vault secret key %q of %s is not an environment name", key, service)
		}
		if _, set := env[key]; set {
			return fmt.Errorf("%s sets %s both in env and as a Vault secret", service, key)
		}
		if files[strings.ToLower(key)] {
			return errors.New("Vault secret keys must name distinct files after lowercasing")
		}
		files[strings.ToLower(key)] = true
		rest, inCell := strings.CutPrefix(ref.Name, cell+"-")
		secretKey, ofService := strings.CutPrefix(rest, service+"-")
		if !ofService {
			// Existing signed profiles retain their cell-number namespace.
			index, legacy, _ := strings.Cut(rest, "-")
			secretKey, ofService = strings.CutPrefix(legacy, service+"-")
			ofService = ofService && index != "" && index[0] != '0' && strings.Trim(index, "0123456789") == ""
		}
		if len(ref.Name) > 255 || !nameRE.MatchString(ref.Name) || !inCell || !ofService || secretKey == "" {
			return fmt.Errorf("Vault secret %s of %s must name %s-%s-<purpose> or an existing %s-<n>-%s-<purpose>", key, service, cell, service, cell, service)
		}
	}
	return nil
}

Resolve.raw_text:
func Resolve(ctx context.Context, refs map[string]Ref, client func(region string) (BundleClient, error)) (map[string]string, error) {
	// Before client fetches an instance principal.
	if err := safeEnv(); err != nil {
		return nil, err
	}
	values := make(map[string]string, len(refs))
	total := 0
	for key, ref := range refs {
		region := ref.region()
		if region == "" {
			return nil, fmt.Errorf("Vault secret %s names no regional Vault", key)
		}
		bundles, err := client(region)
		if err != nil {
			return nil, fmt.Errorf("Vault secret %s: %w", key, err)
		}
		value, err := Read(ctx, bundles, ref.Vault, ref.Name)
		if err != nil {
			return nil, err
		}
		// exec refuses a NUL in the environment.
		if len(value) > maxValue || strings.ContainsRune(value, 0) {
			return nil, fmt.Errorf("Vault secret %s does not fit an environment variable", ref.Name)
		}
		if total += len(key) + len(value); total > maxResolved {
			return nil, fmt.Errorf("Vault secrets exceed %d bytes together", maxResolved)
		}
		values[key] = value
	}
	return values, nil
}

safeEnv.raw_text:
func safeEnv() error {
	for _, variable := range ociclient.SecretUnsafeEnv {
		if _, set := os.LookupEnv(variable); set {
			return fmt.Errorf("OCI Vault access refuses to run while %s is set", variable)
		}
	}
	return nil
}

retrySecretRead.raw_text:
func retrySecretRead(err error) bool {
	var serviceErr common.ServiceError
	if !errors.As(err, &serviceErr) {
		return false
	}
	status := serviceErr.GetHTTPStatusCode()
	return status == http.StatusNotFound || status == http.StatusConflict
}

Absent.raw_text:
func Absent(err error) bool {
	var serviceErr common.ServiceError
	return errors.As(err, &serviceErr) && serviceErr.GetHTTPStatusCode() == http.StatusNotFound
}

Run.raw_text:
func Run(ctx context.Context, args []string, output io.Writer) error {
	if len(args) == 0 || args[0] == "help" || args[0] == "--help" || args[0] == "-h" {
		_, err := io.WriteString(output, usage)
		return err
	}
	flags := flag.NewFlagSet("vault "+args[0], flag.ContinueOnError)
	flags.SetOutput(io.Discard)
	vaultID := flags.String("vault-id", "", "the Vault OCID")
	keyID := flags.String("key-id", "", "the Vault master key OCID")
	compartmentID := flags.String("compartment-id", "", "the compartment of a new secret")
	name := flags.String("name", "", "the secret name")
	file := flags.String("file", "", "the secret value")
	secretID := flags.String("secret-id", "", "the exact secret OCID")
	expected := flags.Int64("expect-current", 0, "the current version the owner read")
	instancePrincipal := flags.Bool("instance-principal", false, "publish as the regional service principal")
	scope := flags.String("scope", "", "the secret name prefix, a cell such as gru-1")
	template := flags.String("template", "", "the template to render")
	out := flags.String("out", "", "the rendered file")
	cell := flags.String("cell", "", "the region name, gru or sfo")
	service := flags.String("service", "", "the owner service")
	refs := flags.String("refs", "", "the public Vault reference JSON file")
	directory := flags.String("dir", "", "the private tmpfs delivery directory")
	refresh := flags.Duration("refresh", time.Minute, "the CURRENT version polling interval")
	once := flags.Bool("once", false, "deliver the current versions once")
	fileNames := flags.Bool("file-names", false, "reference keys are exact filenames for existing signed paths")
	if err := flags.Parse(args[1:]); err != nil {
		return err
	}
	if flags.NArg() != 0 {
		return errors.New("unexpected vault arguments")
	}
	if err := safeEnv(); err != nil {
		return err
	}
	parts := strings.Split(*vaultID, ".")
	region := ""
	if len(parts) >= 5 && parts[1] == "vault" && catalog.IsOCIRegion(parts[3]) {
		region = parts[3]
	}
	switch args[0] {
	case "version":
		if region == "" || *name == "" || *secretID == "" || *expected < 1 || *file == "" {
			return errors.New("version requires --vault-id, --name, --secret-id, --expect-current and --file")
		}
		value, err := readValue(*file)
		if err != nil {
			return err
		}
		defer clear(value)
		var factory *ociclient.Factory
		if *instancePrincipal {
			factory, err = ociclient.InstancePrincipal(region)
		} else {
			factory, err = ociclient.OperatorConfig(region)
		}
		if err != nil {
			return err
		}
		if _, err := Publish(ctx, factory, Ref{Vault: *vaultID, Name: *name}, *secretID, *expected, value); err != nil {
			return err
		}
		return printLine(output, Stored{Secret: *name, ID: *secretID})
	case "deliver":
		if *cell == "" || *service == "" || *refs == "" || *directory == "" || *refresh <= 0 {
			return errors.New("deliver requires --cell, --service, --refs, --dir and a positive --refresh")
		}
		return Deliver(ctx, *cell, *service, *refs, *directory, *refresh, *once, *fileNames, output)
	case "put":
		if *vaultID == "" || *keyID == "" || *compartmentID == "" || *name == "" || *file == "" {
			return errors.New("put requires --vault-id, --key-id, --compartment-id, --name and --file")
		}
		if region == "" || !strings.HasPrefix(*keyID, "ocid1.key.") ||
			!strings.HasPrefix(*compartmentID, "ocid1.compartment.") && !strings.HasPrefix(*compartmentID, "ocid1.tenancy.") {
			return errors.New("put needs a regional Vault, a key and a compartment OCID")
		}
		value, err := readValue(*file)
		if err != nil {
			return err
		}
		defer clear(value)
		factory, err := ociclient.OperatorConfig(region)
		if err != nil {
			return err
		}
		client, err := ocivault.NewVaultsClientWithConfigurationProvider(factory.Provider())
		if err != nil {
			return err
		}
		client.SetRegion(factory.Region())
		factory.Configure(&client.BaseClient, ociclient.ServiceVault)
		bundles, err := SecretsClient(factory)
		if err != nil {
			return err
		}
		stored, err := Put(ctx, client, bundles, Target{CompartmentID: *compartmentID, VaultID: *vaultID, KeyID: *keyID}, *name, value)
		if err != nil {
			return err
		}
		return printLine(output, stored)
	case "render":
		if *vaultID == "" || *scope == "" || *template == "" || *out == "" {
			return errors.New("render requires --vault-id, --scope, --template and --out")
		}
		if region == "" || !nameRE.MatchString(*scope) {
			return errors.New("render needs a regional Vault OCID and a lowercase hyphenated scope")
		}
		if os.Geteuid() != 0 {
			return errors.New("render runs as root: its file holds secrets")
		}
		root, err := openMemoryDirectory(filepath.Dir(*out))
		if err != nil {
			return err
		}
		defer root.Close()
		text, err := os.ReadFile(*template)
		if err != nil {
			return err
		}
		factory, err := ociclient.InstancePrincipal(region)
		if err != nil {
			return err
		}
		bundles, err := SecretsClient(factory)
		if err != nil {
			return err
		}
		rendered, names, err := Render(ctx, bundles, *vaultID, *scope, text)
		if err != nil {
			return err
		}
		defer clear(rendered)
		if err := writeMemoryFile(root, filepath.Base(*out), rendered); err != nil {
			return err
		}
		return printLine(output, map[string]any{"file": *out, "secrets": names})
	default:
		_, _ = io.WriteString(output, usage)
		return fmt.Errorf("unknown vault command %q", args[0])
	}
}

Put.raw_text:
func Put(ctx context.Context, client VaultClient, bundles BundleClient, target Target, name string, value []byte) (Stored, error) {
	if len(name) > 255 || !nameRE.MatchString(name) || strings.Count(name, "-") < 2 {
		return Stored{}, fmt.Errorf("secret name %q must be lowercase words joined by hyphens: <scope>-<service>-<key>", name)
	}
	if len(value) == 0 || len(value) > maxValue {
		return Stored{}, fmt.Errorf("secret %s must hold 1 to %d bytes", name, maxValue)
	}
	stored, err := Ensure(ctx, client, target, name, name+"; stored once by ts-orch vault put.",
		func(context.Context) (string, error) { return string(value), nil })
	if err != nil {
		return stored, err
	}
	current, err := ReadBack(ctx, bundles, target.VaultID, name, stored.Created || stored.Provisioning)
	if err != nil {
		return stored, err
	}
	if subtle.ConstantTimeCompare([]byte(current), value) != 1 {
		return stored, fmt.Errorf("Vault secret %s differs from the file; inspect it before rerunning", name)
	}
	return stored, nil
}

ReadBack.raw_text:
func ReadBack(ctx context.Context, client BundleClient, vaultID, name string, created bool) (string, error) {
	for attempt := 1; ; attempt++ {
		value, err := Read(ctx, client, vaultID, name)
		if err == nil || !created || attempt == 30 || !retrySecretRead(err) {
			return value, err
		}
		select {
		case <-ctx.Done():
			return "", ctx.Err()
		case <-time.After(2 * time.Second):
		}
	}
}

Render.raw_text:
func Render(ctx context.Context, bundles BundleClient, vaultID, scope string, template []byte) ([]byte, []string, error) {
	if bytes.Contains(placeholderRE.ReplaceAll(template, nil), []byte("{{")) {
		return nil, nil, errors.New("template placeholders must be {{KEY}} with KEY in A-Z, 0-9 and _")
	}
	values := map[string][]byte{}
	names := []string{}
	for _, match := range placeholderRE.FindAllSubmatch(template, -1) {
		key := string(match[1])
		if values[key] != nil {
			continue
		}
		name := Name(scope, key)
		value, err := Read(ctx, bundles, vaultID, name)
		if err != nil {
			return nil, nil, err
		}
		if values[key], err = json.Marshal(value); err != nil {
			return nil, nil, fmt.Errorf("Vault secret %s is not valid UTF-8", name)
		}
		names = append(names, name)
	}
	rendered := placeholderRE.ReplaceAllFunc(template, func(match []byte) []byte {
		return values[string(match[2:len(match)-2])]
	})
	for _, value := range values {
		clear(value)
	}
	return rendered, names, nil
}

PublishVersion.raw_text:
func PublishVersion(ctx context.Context, client VersionClient, ref Ref, id string, expected int64, value []byte) (Stored, error) {
	if err := safeEnv(); err != nil {
		return Stored{}, err
	}
	if ref.region() == "" || !nameRE.MatchString(ref.Name) || len(ref.Name) > 255 ||
		!secretOCIDRE.MatchString(id) || strings.Split(id, ".")[3] != ref.region() || expected < 1 || len(value) == 0 || len(value) > maxValue {
		return Stored{}, errors.New("Vault publication requires a regional named secret, an expected version and 1 to 16384 bytes")
	}
	before, err := client.GetSecret(ctx, ocivault.GetSecretRequest{SecretId: new(id)})
	if err != nil {
		return Stored{}, fmt.Errorf("read Vault metadata for %s failed", ref.Name)
	}
	if before.Id == nil || *before.Id != id || before.VaultId == nil || *before.VaultId != ref.Vault ||
		before.SecretName == nil || *before.SecretName != ref.Name ||
		before.LifecycleState != ocivault.SecretLifecycleStateActive || before.Etag == nil || *before.Etag == "" {
		return Stored{}, errors.New("Vault publication target differs from its named regional reference")
	}
	if before.CurrentVersionNumber == nil || *before.CurrentVersionNumber != expected {
		return Stored{}, ErrVersionConflict
	}
	content := base64.StdEncoding.EncodeToString(value)
	after, err := client.UpdateSecret(ctx, ocivault.UpdateSecretRequest{
		SecretId: new(id), IfMatch: before.Etag,
		UpdateSecretDetails: ocivault.UpdateSecretDetails{SecretContent: ocivault.Base64SecretContentDetails{
			Content: new(content), Stage: ocivault.SecretContentDetailsStageCurrent,
		}},
	})
	if err != nil {
		return Stored{}, fmt.Errorf("publish Vault secret %s failed; reread CURRENT before retrying", ref.Name)
	}
	if after.Id == nil || *after.Id != id || after.CurrentVersionNumber == nil || *after.CurrentVersionNumber <= expected {
		return Stored{}, errors.New("Vault publication returned uncertain version metadata; reread CURRENT before retrying")
	}
	return Stored{Secret: ref.Name, ID: id}, nil
}

fakeVault.raw_text:
// fakeVault keeps secrets in memory.
type fakeVault struct {
	items   []ocivault.SecretSummary
	bundles map[string]ocisecrets.SecretBundleContentDetails
	creates []ocivault.CreateSecretRequest
	reads   []ocisecrets.GetSecretBundleByNameRequest
}

func newVault() *fakeVault {
	return &fakeVault{bundles: map[string]ocisecrets.SecretBundleContentDetails{}}
}

func (v *fakeVault) store(name, value string) {
	v.items = append(v.items, ocivault.SecretSummary{Id: new("ocid1.vaultsecret.oc1.sa-saopaulo-1.amaaaa" + strconv.Itoa(len(v.items)+1)),
		SecretName: new(name), LifecycleState: ocivault.SecretSummaryLifecycleStateActive})
	v.bundles[name] = ocisecrets.Base64SecretBundleContentDetails{Content: new(base64.StdEncoding.EncodeToString([]byte(value)))}
}

func (v *fakeVault) ListSecrets(_ context.Context, request ocivault.ListSecretsRequest) (ocivault.ListSecretsResponse, error) {
	return ocivault.ListSecretsResponse{Items: v.items}, nil
}

func (v *fakeVault) CreateSecret(_ context.Context, request ocivault.CreateSecretRequest) (ocivault.CreateSecretResponse, error) {
	v.creates = append(v.creates, request)
	details := request.CreateSecretDetails
	content := details.SecretContent.(ocivault.Base64SecretContentDetails)
	value, _ := base64.StdEncoding.DecodeString(*content.Content)
	v.store(*details.SecretName, string(value))
	return ocivault.CreateSecretResponse{Secret: ocivault.Secret{Id: v.items[len(v.items)-1].Id}}, nil
}

func (v *fakeVault) GetSecretBundleByName(_ context.Context, request ocisecrets.GetSecretBundleByNameRequest) (ocisecrets.GetSecretBundleByNameResponse, error) {
	v.reads = append(v.reads, request)
	content, ok := v.bundles[*request.SecretName]
	if !ok {
		return ocisecrets.GetSecretBundleByNameResponse{}, errors.New("secret not found")
	}
	return ocisecrets.GetSecretBundleByNameResponse{SecretBundle: ocisecrets.SecretBundle{SecretBundleContent: content}}, nil
}

