deposeOnList.raw_text:
// deposeOnList moves the epoch on once the pass has listed OCI volumes.
type deposeOnList struct {
	*testFence
	cloud *fakeCloud
}

func (f deposeOnList) Guard(ctx context.Context, epoch uint64) error {
	f.cloud.mu.Lock()
	listed := len(f.cloud.calls) > 0
	f.cloud.mu.Unlock()
	if listed {
		f.epoch.Store(epoch + 1)
	}
	return f.testFence.Guard(ctx, epoch)
}

equalPrefix.raw_text:
func equalPrefix(got, want []string) bool {
	return len(got) >= len(want) && strings.Join(got[:len(want)], ",") == strings.Join(want, ",")
}

Pass.raw_text:
func (r *Reconciler) Pass(ctx context.Context) error {
	snapshot := r.Fencer.Current()
	if !snapshot.CanMutate() {
		return nil
	}
	if err := r.Settings.Validate(); err != nil {
		return err
	}
	owner, err := naming.RegionCell(r.Store.region).Name()
	if err != nil {
		return err
	}
	records, err := r.Store.List(ctx)
	if err != nil {
		return err
	}
	p := &pass{Reconciler: r, epoch: snapshot.Epoch, owner: owner}
	var errs []error
	for _, v := range records {
		if v.Destroying() || v.Status.State == StateDestroyed {
			continue
		}
		if err := p.reconcile(ctx, v); err != nil {
			errs = append(errs, fmt.Errorf("volume %s: %w", v.ID, err))
		}
	}
	return errors.Join(errs...)
}

reconcile.raw_text:
func (p *pass) reconcile(ctx context.Context, v Volume) error {
	status, err := p.converge(ctx, v)
	if errors.Is(err, errHold) {
		status = v.Status
		status.State, status.Message = StateFailed, err.Error()
		err = nil
	}
	if err != nil {
		return err
	}
	if status == v.Status {
		return nil
	}
	status.Epoch = p.epoch
	if err := p.guard(ctx); err != nil {
		return err
	}
	v.Status = status
	_, err = p.Store.Update(ctx, v)
	return err
}

converge.raw_text:
func (p *pass) converge(ctx context.Context, v Volume) (Status, error) {
	cloud, err := p.observe(ctx, v)
	if err != nil {
		return Status{}, err
	}
	if cloud.ID == "" {
		if cloud, err = p.create(ctx, v); err != nil {
			return Status{}, err
		}
	}
	status := v.Status
	status.OCID, status.Message = cloud.ID, ""
	switch cloud.State {
	case "PROVISIONING", "RESTORING":
		if status.State != StateCreating {
			return Status{}, hold("OCI volume %s is %s", cloud.ID, cloud.State)
		}
		return status, nil
	case "AVAILABLE":
	default:
		return Status{}, hold("OCI volume %s is %s", cloud.ID, cloud.State)
	}
	status.State, status.SizeGB = StateCreated, cloud.SizeGB
	// One change per pass: OCI applies them one at a time, and the next
	// pass reads the new ETag.
	switch {
	case v.SizeGB > cloud.SizeGB:
		if err := p.guard(ctx); err != nil {
			return Status{}, err
		}
		return status, p.Cloud.ResizeVolume(ctx, cloud.ID, cloud.ETag, v.SizeGB)
	case v.VPUsPerGB != cloud.VPUsPerGB:
		if err := p.guard(ctx); err != nil {
			return Status{}, err
		}
		return status, p.Cloud.SetVolumePerformance(ctx, cloud.ID, cloud.ETag, v.VPUsPerGB)
	}
	return status, p.ensurePolicy(ctx, v, cloud.ID)
}

observe.raw_text:
func (p *pass) observe(ctx context.Context, v Volume) (CloudVolume, error) {
	if v.Zone != p.Settings.Zone {
		return CloudVolume{}, hold("zone %s is not this cell's zone %s", v.Zone, p.Settings.Zone)
	}
	id := v.Status.OCID
	if id == "" {
		if !p.listed {
			volumes, err := p.Cloud.ListVolumes(ctx, p.Settings.CompartmentID, p.Settings.Zone)
			if err != nil {
				return CloudVolume{}, err
			}
			p.volumes, p.listed = volumes, true
		}
		var found []string
		for _, cloud := range p.volumes {
			if p.owns(cloud, v) {
				found = append(found, cloud.ID)
			}
		}
		switch len(found) {
		case 0:
			return CloudVolume{}, nil
		case 1:
			id = found[0]
		default:
			return CloudVolume{}, hold("%d OCI volumes carry volume %s", len(found), v.ID)
		}
	}
	cloud, err := p.Cloud.GetVolume(ctx, id)
	switch {
	case errors.Is(err, ErrGone):
		return CloudVolume{}, hold("OCI volume %s is gone", id)
	case err != nil:
		return CloudVolume{}, err
	case !p.owns(cloud, v):
		return CloudVolume{}, hold("OCI volume %s is not this cell's volume %s", id, v.ID)
	case cloud.KMSKeyID != p.Settings.KMSKeyID:
		// A changed cell key holds the volume until an operator re-keys it.
		return CloudVolume{}, hold("OCI volume %s is not encrypted with the cell's KMS key", id)
	}
	return cloud, nil
}

owns.raw_text:
func (p *pass) owns(cloud CloudVolume, v Volume) bool {
	return cloud.Tags[tagManagedBy] == managedBy && cloud.Tags[tagOwner] == p.owner &&
		cloud.Tags[tagResource] == resourceVolume && cloud.Tags[tagCreateKey] == v.ID &&
		cloud.CompartmentID == p.Settings.CompartmentID && cloud.Zone == v.Zone
}

retryToken.raw_text:
func retryToken(parts ...string) string {
	sum := sha256.Sum256([]byte(strings.Join(parts, ":")))
	return hex.EncodeToString(sum[:])
}

create.raw_text:
func (p *pass) create(ctx context.Context, v Volume) (CloudVolume, error) {
	if v.Status.State != StateCreating {
		return CloudVolume{}, hold("volume %s lost its OCI volume", v.ID)
	}
	if err := p.guard(ctx); err != nil {
		return CloudVolume{}, err
	}
	return p.Cloud.CreateVolume(ctx, CreateRequest{
		CompartmentID: p.Settings.CompartmentID, Zone: v.Zone, DisplayName: p.owner + "-" + v.App + "-" + v.ID,
		SizeGB: v.SizeGB, VPUsPerGB: v.VPUsPerGB, KMSKeyID: p.Settings.KMSKeyID,
		Tags: map[string]string{tagManagedBy: managedBy, tagOwner: p.owner, tagResource: resourceVolume,
			tagCreateKey: v.ID, tagApp: v.App},
		RetryToken: retryToken(managedBy, p.owner, resourceVolume, v.ID),
	})
}

policy.raw_text:
func (p *pass) policy(days int) BackupPolicy {
	return BackupPolicy{Name: fmt.Sprintf("%s-volumes-%dd", p.owner, days),
		Tags:      map[string]string{tagManagedBy: managedBy, tagOwner: p.owner, tagResource: resourcePolicy},
		Schedules: []Schedule{{Type: "INCREMENTAL", Period: "ONE_DAY", RetentionSeconds: days * 24 * 3600}}}
}

ownPolicy.raw_text:
func (p *pass) ownPolicy(ctx context.Context, want BackupPolicy) (BackupPolicy, bool, error) {
	if p.policies == nil {
		policies, err := p.Cloud.ListBackupPolicies(ctx, p.Settings.CompartmentID)
		if err != nil {
			return BackupPolicy{}, false, err
		}
		p.policies = policies
	}
	for _, policy := range p.policies {
		if policy.Name != want.Name {
			continue
		}
		if !maps.Equal(policy.Tags, want.Tags) || !slices.Equal(policy.Schedules, want.Schedules) {
			return BackupPolicy{}, false, hold("backup policy %s is not this cell's", want.Name)
		}
		return policy, true, nil
	}
	return BackupPolicy{}, false, nil
}

cellPolicy.raw_text:
func (p *pass) cellPolicy(policy BackupPolicy) bool {
	for days := 1; days <= maxSnapshotRetentionDays; days++ {
		want := p.policy(days)
		if policy.Name == want.Name {
			return maps.Equal(policy.Tags, want.Tags) && slices.Equal(policy.Schedules, want.Schedules)
		}
	}
	return false
}

ensurePolicy.raw_text:
func (p *pass) ensurePolicy(ctx context.Context, v Volume, volumeID string) error {
	want := p.policy(v.SnapshotRetentionDays)
	policy, found, err := p.ownPolicy(ctx, want)
	if err != nil {
		return err
	}
	if !found {
		if err := p.guard(ctx); err != nil {
			return err
		}
		if policy, err = p.Cloud.CreateBackupPolicy(ctx, p.Settings.CompartmentID, want,
			retryToken(managedBy, p.owner, resourcePolicy, want.Name)); err != nil {
			return err
		}
		p.policies = append(p.policies, policy)
	}
	current, err := p.Cloud.PolicyAssignment(ctx, volumeID)
	if err != nil || current.PolicyID == policy.ID {
		return err
	}
	if current.ID != "" {
		ours := slices.ContainsFunc(p.policies, func(old BackupPolicy) bool {
			return old.ID == current.PolicyID && p.cellPolicy(old)
		})
		if !ours {
			return hold("OCI volume %s carries backup policy %s, which is not this cell's", volumeID, current.PolicyID)
		}
		if err := p.guard(ctx); err != nil {
			return err
		}
		if err := p.Cloud.DeleteAssignment(ctx, current.ID); err != nil {
			return err
		}
	}
	if err := p.guard(ctx); err != nil {
		return err
	}
	return p.Cloud.AssignPolicy(ctx, volumeID, policy.ID)
}

Settings.Validate.raw_text:
const (
	tagManagedBy   = "terrascale-managed-by"
	tagOwner       = "terrascale-owner"
	tagResource    = "terrascale-resource"
	tagCreateKey   = "terrascale-create-key"
	tagApp         = "terrascale-app"
	managedBy      = "ts-orchestrator"
	resourceVolume = "managed-volume"
	resourcePolicy = "managed-volume-backup-policy"
)

// Settings are a cell's managed volume settings.
//
// ponytail: one availability domain per cell, which every current region
// has; a multi-AD region lists its zones here.
type Settings struct {
	CompartmentID string `json:"compartment_id"`
	Zone          string `json:"zone"`
	// KMSKeyID is the regional Vault key every new volume is encrypted with.
	KMSKeyID string `json:"kms_key_id"`
}

// Validate requires a compartment, a zone and a KMS key.
func (s Settings) Validate() error {
	if !isOCID(s.CompartmentID, "compartment") || !zoneRE.MatchString(s.Zone) || !isOCID(s.KMSKeyID, "key") {
		return fmt.Errorf("%w: managed volumes need a compartment OCID, a zone and a KMS key OCID", ErrInvalid)
	}
	return nil
}

// errHold marks a volume the reconciler must not act on: its record is
// marked failed with the reason until an operator resolves it.
var errHold = errors.New("managed volume needs an operator")

func hold(format string, args ...any) error {
	return fmt.Errorf("%w: %s", errHold, fmt.Sprintf(format, args...))
}

OpenStore.raw_text:
func OpenStore(ctx context.Context, js jetstream.JetStream, region string, replicas int) (*Store, error) {
	if js == nil || !validRegion(region) || replicas != 1 && replicas != 3 && replicas != 5 {
		return nil, fmt.Errorf("%w: volume store configuration", ErrInvalid)
	}
	kv, err := js.CreateOrUpdateKeyValue(ctx, jetstream.KeyValueConfig{
		Bucket: Bucket, Description: "Managed volume records", Storage: jetstream.FileStorage,
		Replicas: replicas, History: 8, MaxValueSize: maxRecordBytes,
	})
	if err != nil {
		return nil, fmt.Errorf("volume store: %w", err)
	}
	return &Store{kv: kv, region: region}, nil
}

Store.Create.raw_text:
func (s *Store) Create(ctx context.Context, v Volume) (Volume, error) {
	if err := v.Validate(); err != nil {
		return Volume{}, err
	}
	if v.Region != s.region || v.MachineID != "" || v.Destroying() || v.Status != (Status{State: StateCreating}) {
		return Volume{}, fmt.Errorf("%w: a new volume of %s starts creating with no machine", ErrInvalid, s.region)
	}
	wire, err := protocol.EncodeJSON(v)
	if err != nil {
		return Volume{}, err
	}
	revision, err := s.kv.Create(ctx, v.ID, wire)
	if errors.Is(err, jetstream.ErrKeyExists) {
		return Volume{}, fmt.Errorf("%w: volume %s exists", ErrConflict, v.ID)
	}
	if err != nil {
		return Volume{}, fmt.Errorf("create volume %s: %w", v.ID, err)
	}
	v.Revision = revision
	return v, nil
}

Store.Get.raw_text:
func (s *Store) Get(ctx context.Context, id string) (Volume, error) {
	if !entityid.Valid(id) {
		return Volume{}, fmt.Errorf("%w: id %q", ErrInvalid, id)
	}
	entry, err := s.kv.Get(ctx, id)
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return Volume{}, fmt.Errorf("%w: %s", ErrNotFound, id)
	}
	if err != nil {
		return Volume{}, fmt.Errorf("read volume %s: %w", id, err)
	}
	return s.decode(id, entry)
}

Store.decode.raw_text:
func (s *Store) decode(id string, entry jetstream.KeyValueEntry) (Volume, error) {
	var v Volume
	if err := protocol.DecodeStrict(entry.Value(), &v, maxRecordBytes); err != nil {
		return Volume{}, fmt.Errorf("%w: record %s: %w", ErrInvalid, id, err)
	}
	if err := v.Validate(); err != nil {
		return Volume{}, fmt.Errorf("record %s: %w", id, err)
	}
	if v.ID != id || v.Region != s.region {
		return Volume{}, fmt.Errorf("%w: record %s holds volume %s of %s", ErrInvalid, id, v.ID, v.Region)
	}
	v.Revision = entry.Revision()
	return v, nil
}

Store.List.raw_text:
func (s *Store) List(ctx context.Context) ([]Volume, error) {
	watcher, err := s.kv.WatchAll(ctx, jetstream.IgnoreDeletes())
	if err != nil {
		return nil, fmt.Errorf("list volumes: %w", err)
	}
	defer func() {
		_ = watcher.Stop()
		// A delivery blocked on the full channel finishes, and the closed
		// subscription then closes the channel and ends this drain.
		go func() {
			for range watcher.Updates() {
			}
		}()
	}()
	var volumes []Volume
	for {
		var entry jetstream.KeyValueEntry
		open := false
		select {
		case entry, open = <-watcher.Updates():
		case <-ctx.Done():
			return nil, fmt.Errorf("list volumes: %w", ctx.Err())
		}
		switch {
		case !open:
			// The subscription closed before the initial values ended, for
			// example on a lost connection: the list would be partial.
			return nil, errors.New("list volumes: the key watch ended early")
		case entry == nil:
			slices.SortFunc(volumes, func(a, b Volume) int { return strings.Compare(a.ID, b.ID) })
			return volumes, nil
		case len(volumes) == maxListed:
			return nil, errors.New("volume list exceeds its safety bound")
		}
		v, err := s.decode(entry.Key(), entry)
		if err != nil {
			return nil, err
		}
		volumes = append(volumes, v)
	}
}

Store.Update.raw_text:
func (s *Store) Update(ctx context.Context, v Volume) (Volume, error) {
	prev, err := s.Get(ctx, v.ID)
	if err != nil {
		return Volume{}, err
	}
	if prev.Revision != v.Revision {
		return Volume{}, fmt.Errorf("%w: volume %s is at revision %d, not %d", ErrConflict, v.ID, prev.Revision, v.Revision)
	}
	if err := checkUpdate(prev, v); err != nil {
		return Volume{}, err
	}
	wire, err := protocol.EncodeJSON(v)
	if err != nil {
		return Volume{}, err
	}
	revision, err := s.kv.Update(ctx, v.ID, wire, v.Revision)
	if errors.Is(err, jetstream.ErrKeyRevisionMismatch) {
		return Volume{}, fmt.Errorf("%w: volume %s", ErrConflict, v.ID)
	}
	if err != nil {
		return Volume{}, fmt.Errorf("update volume %s: %w", v.ID, err)
	}
	v.Revision = revision
	return v, nil
}

volumeValidation.raw_text:
// SchemaVersion is the version of a stored volume record.
const SchemaVersion = 1

// OCI block volume limits and the Fly-style defaults an API applies.
const (
	MinSizeGB                    = 50
	MaxSizeGB                    = 32768
	DefaultVPUsPerGB             = 10
	DefaultSnapshotRetentionDays = 5
	maxSnapshotRetentionDays     = 60
	maxVPUsPerGB                 = 120
	maxMessageBytes              = 1024
)

var (
	ErrInvalid  = errors.New("invalid managed volume")
	ErrNotFound = errors.New("managed volume does not exist")
	// ErrConflict marks a lost compare-and-set race; re-read and retry.
	ErrConflict = errors.New("managed volume changed concurrently")
	// ErrTransition marks a change the volume's current record forbids.
	ErrTransition = errors.New("managed volume change is not allowed")
)

var (
	// appRE and machineRE are internal/machines' app name and machine ID
	// rules.
	appRE  = regexp.MustCompile(`^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$`)
	nameRE = regexp.MustCompile(`^[a-z0-9_]{1,30}$`)
	zoneRE = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9:._-]{0,127}$`)
)

// State is the reconciler's view of a volume. Growing, restoring and
// attaching show in the spec and status fields and need no state of their
// own.
type State string

const (
	// StateCreating: the record exists and OCI has not confirmed the volume.
	StateCreating State = "creating"
	// StateCreated: the OCI volume is available.
	StateCreated State = "created"
	// StatePendingDestroy: destroy was requested; the OCI volume still exists.
	StatePendingDestroy State = "pending_destroy"
	// StateDestroyed: the OCI volume is deleted. Nothing changes afterwards.
	StateDestroyed State = "destroyed"
	// StateFailed: the OCI volume is lost or unusable and needs an operator.
	StateFailed State = "failed"
)

// transitions lists the states each state may move to.
var transitions = map[State][]State{
	StateCreating:       {StateCreated, StateFailed},
	StateCreated:        {StateFailed, StatePendingDestroy},
	StateFailed:         {StateCreated, StatePendingDestroy},
	StatePendingDestroy: {StateDestroyed},
	StateDestroyed:      nil,
}

// Volume is one record of the TS_VOLUMES bucket. The creator sets the
// identity, the API the size, tier, retention and destroy request, the
// scheduler MachineID and the reconciler Status.
type Volume struct {
	SchemaVersion int    `json:"schema_version"`
	ID            string `json:"id"`
	App           string `json:"app"`
	// Name is not unique: an app scales by giving several machines a volume
	// of the same name.
	Name string `json:"name"`
	// Region is the lower-case catalog name, for example gru, as in
	// internal/machines.
	Region string `json:"region"`
	// Zone is the OCI availability domain, fixed at create.
	Zone string `json:"zone"`
	// SizeGB is the desired size. It only grows.
	SizeGB int64 `json:"size_gb"`
	// VPUsPerGB is the OCI performance tier: 0 (Lower Cost), 10 (Balanced)
	// or 20 to 120 in steps of 10.
	VPUsPerGB int `json:"vpus_per_gb"`
	// SnapshotRetentionDays is Fly's snapshot_retention: days of daily
	// snapshots.
	SnapshotRetentionDays int `json:"snapshot_retention"`
	// MachineID is the machine that may mount the volume.
	MachineID          string    `json:"machine_id,omitempty"`
	CreatedAt          time.Time `json:"created_at"`
	DestroyRequestedAt time.Time `json:"destroy_requested_at,omitzero"`
	Status             Status    `json:"status"`
	// Revision is the KV revision the record was read at; it is not stored.
	Revision uint64 `json:"-"`
}

// Status is written by the reconciler.
type Status struct {
	State State `json:"state"`
	// Epoch is the authority epoch of the reconciler that wrote the status.
	// It never goes back, so a deposed leader cannot overwrite a newer
	// observation.
	Epoch uint64 `json:"epoch,omitzero"`
	// OCID is the OCI volume. Once recorded it never changes.
	OCID string `json:"ocid,omitempty"`
	// SizeGB is the size OCI confirmed. It may exceed the desired size: an
	// adopted volume or one grown outside the orchestrator stays larger,
	// because OCI never shrinks a volume.
	SizeGB int64 `json:"size_gb,omitzero"`
	// AttachedMachineID is the machine whose host OCI attaches the volume
	// to. It differs from the desired MachineID while the volume moves: the
	// reconciler detaches it from this machine, after proof that it stopped,
	// before it attaches the volume to MachineID.
	AttachedMachineID string `json:"attached_machine_id,omitempty"`
	Message           string `json:"message,omitempty"`
}

// NewID returns a fresh canonical ULID for a volume.
func NewID() string { return entityid.New() }

// Destroying reports whether destroy was requested.
func (v Volume) Destroying() bool { return !v.DestroyRequestedAt.IsZero() }

// Validate checks the shape of one record.
func (v Volume) Validate() error {
	switch {
	case v.SchemaVersion != SchemaVersion:
		return fmt.Errorf("%w: schema version %d", ErrInvalid, v.SchemaVersion)
	case !entityid.Valid(v.ID):
		return fmt.Errorf("%w: id %q", ErrInvalid, v.ID)
	case !appRE.MatchString(v.App):
		return fmt.Errorf("%w: app %q", ErrInvalid, v.App)
	case !nameRE.MatchString(v.Name):
		return fmt.Errorf("%w: name %q must be 1 to 30 of a-z, 0-9 and _", ErrInvalid, v.Name)
	case !validRegion(v.Region):
		return fmt.Errorf("%w: region %q", ErrInvalid, v.Region)
	case !zoneRE.MatchString(v.Zone):
		return fmt.Errorf("%w: zone %q", ErrInvalid, v.Zone)
	case v.SizeGB < MinSizeGB || v.SizeGB > MaxSizeGB:
		return fmt.Errorf("%w: size must be %d to %d GB", ErrInvalid, MinSizeGB, MaxSizeGB)
	case v.VPUsPerGB < 0 || v.VPUsPerGB > maxVPUsPerGB || v.VPUsPerGB%10 != 0:
		return fmt.Errorf("%w: vpus_per_gb must be 0 to %d in steps of 10", ErrInvalid, maxVPUsPerGB)
	case v.SnapshotRetentionDays < 1 || v.SnapshotRetentionDays > maxSnapshotRetentionDays:
		return fmt.Errorf("%w: snapshot retention must be 1 to %d days", ErrInvalid, maxSnapshotRetentionDays)
	case v.MachineID != "" && !entityid.Valid(v.MachineID):
		return fmt.Errorf("%w: machine %q", ErrInvalid, v.MachineID)
	case v.CreatedAt.IsZero():
		return fmt.Errorf("%w: no creation time", ErrInvalid)
	}
	if v.Destroying() && v.MachineID != "" {
		return fmt.Errorf("%w: a destroying volume has no machine", ErrInvalid)
	}
	return v.Status.validate(v.Destroying())
}

func (s Status) validate(destroying bool) error {
	if _, ok := transitions[s.State]; !ok {
		return fmt.Errorf("%w: state %q", ErrInvalid, s.State)
	}
	switch {
	case s.OCID != "" && !isOCID(s.OCID, "volume"):
		return fmt.Errorf("%w: status ocid %q", ErrInvalid, s.OCID)
	case s.State == StateCreated && s.OCID == "":
		return fmt.Errorf("%w: a created volume has an OCID", ErrInvalid)
	case s.SizeGB != 0 && (s.SizeGB < MinSizeGB || s.SizeGB > MaxSizeGB):
		return fmt.Errorf("%w: status size", ErrInvalid)
	case s.AttachedMachineID != "" && (!entityid.Valid(s.AttachedMachineID) || s.OCID == ""):
		return fmt.Errorf("%w: attached machine %q", ErrInvalid, s.AttachedMachineID)
	case len(s.Message) > maxMessageBytes:
		return fmt.Errorf("%w: status message is too long", ErrInvalid)
	case (s.State == StatePendingDestroy || s.State == StateDestroyed) && !destroying:
		return fmt.Errorf("%w: %s without a destroy request", ErrInvalid, s.State)
	case s.State == StateDestroyed && s.AttachedMachineID != "":
		return fmt.Errorf("%w: a destroyed volume is attached", ErrInvalid)
	}
	return nil
}

func validRegion(region string) bool {
	_, ok := catalog.LookupName(region)
	return ok
}

// isOCID is internal/oci's OCID rule.
func isOCID(value, kind string) bool {
	return strings.HasPrefix(value, "ocid1."+kind+".") && len(value) <= 255 && !strings.ContainsAny(value, " \t\r\n")
}

// checkUpdate refuses a change the stored record prev forbids.
func checkUpdate(prev, next Volume) error {
	if err := next.Validate(); err != nil {
		return err
	}
	fail := func(format string, args ...any) error {
		return fmt.Errorf("%w: volume %s: %s", ErrTransition, prev.ID, fmt.Sprintf(format, args...))
	}
	switch {
	case prev.Status.State == StateDestroyed:
		return fail("it is destroyed")
	case next.ID != prev.ID || next.App != prev.App || next.Name != prev.Name || next.Region != prev.Region ||
		next.Zone != prev.Zone || !next.CreatedAt.Equal(prev.CreatedAt):
		return fail("its identity and zone never change")
	case next.SizeGB < prev.SizeGB || next.Status.SizeGB < prev.Status.SizeGB:
		return fail("it only grows")
	case prev.Destroying() && !next.DestroyRequestedAt.Equal(prev.DestroyRequestedAt):
		return fail("a destroy request is final")
	case prev.MachineID != "" && (next.MachineID != "" && next.MachineID != prev.MachineID || next.Destroying()):
		return fail("it is held by machine %s; release it first", prev.MachineID)
	case next.Status != prev.Status && (next.Status.Epoch == 0 || next.Status.Epoch < prev.Status.Epoch):
		return fail("its status was written at epoch %d; a status write needs that epoch or later", prev.Status.Epoch)
	case prev.Status.OCID != "" && next.Status.OCID != prev.Status.OCID:
		return fail("its OCI volume never changes")
	case next.Status.State != prev.Status.State && !slices.Contains(transitions[prev.Status.State], next.Status.State):
		return fail("state %s cannot become %s", prev.Status.State, next.Status.State)
	}
	return nil
}

protocol.raw_text:
func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

// DecodeStrict decodes one bounded JSON value, rejecting duplicate names, invalid
// UTF-8, and unknown struct members. The Go 1.27 JSON v2 decoder rejects duplicate
// object names and invalid UTF-8 by default; RejectUnknownMembers closes the
// remaining permissive struct-decoding path.
func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

// DecodeTolerant is DecodeStrict for records a newer binary may have written:
// it skips members this binary does not know, so binary N-1 reads N's records.
// Duplicate names, invalid UTF-8 and the size limit still fail. A record's
// schema version names its breaking changes, and its reader checks it; a new
// member needs a safe zero value, since an older writer drops it.
func DecodeTolerant(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, false)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}

